css:
.cyber-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Consolas', monospace;
    color: #c9d1d9;
}
.cyber-sim-header {
    border-left: 4px solid #ff4444;
    padding: 20px 28px;
    margin-bottom: 24px;
    background: rgba(255,68,68,0.05);
}
.cyber-sim-header-icon {
    font-size: 2rem;
    margin-bottom: 8px;
}
.cyber-sim-header h1 {
    color: #ff4444;
    font-size: 1.5rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
}
.cyber-sim-subtitle {
    color: #8b949e;
    font-size: 0.85rem;
    margin: 0;
    font-style: italic;
}
.cyber-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #8b949e;
    margin-bottom: 24px;
    padding: 12px;
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
}
.cyber-sim-period-counter span {
    margin: 0 4px;
}
.cyber-sim-period-counter #currentDay {
    color: #ff4444;
    font-weight: 700;
    font-size: 1.4rem;
}
.cyber-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.cyber-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 16px;
    position: relative;
    overflow: hidden;
    text-align: center;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.cyber-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(0,0,0,0.3);
}
.cyber-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
}
.cyber-sim-kpi-cash::before {
    background: linear-gradient(90deg, #ff4444, #ff6b6b);
}
.cyber-sim-kpi-rep::before {
    background: linear-gradient(90deg, #00bfff, #60d0ff);
}
.cyber-sim-kpi-data::before {
    background: linear-gradient(90deg, #ffaa00, #ffc850);
}
.cyber-sim-kpi-sec::before {
    background: linear-gradient(90deg, #00ff88, #50ffaa);
}
.cyber-sim-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 10px;
}
.cyber-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
}
.cyber-sim-kpi-cash .cyber-sim-kpi-value {
    color: #ff4444;
}
.cyber-sim-kpi-rep .cyber-sim-kpi-value {
    color: #00bfff;
}
.cyber-sim-kpi-data .cyber-sim-kpi-value {
    color: #ffaa00;
}
.cyber-sim-kpi-sec .cyber-sim-kpi-value {
    color: #00ff88;
}
.cyber-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #ffaa00;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
}
.cyber-sim-briefing-header {
    color: #ffaa00;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 1px solid #1f2d3d;
}
.cyber-sim-briefing-text {
    font-size: 0.88rem;
    line-height: 1.7;
    color: #c9d1d9;
}
.cyber-sim-briefing-text b {
    color: #ff4444;
}
.cyber-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
}
.cyber-sim-controls h3 {
    color: #ff4444;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 20px;
    padding-bottom: 8px;
    border-bottom: 1px solid #1f2d3d;
}
.cyber-sim-control-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 16px;
}
.cyber-sim-control-group {
    margin-bottom: 4px;
}
.cyber-sim-control-group label {
    display: block;
    color: #8b949e;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 8px;
}
.cyber-sim-container input[type="number"],
.cyber-sim-container select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 10px 14px;
    width: 100%;
    font-family: 'Courier New', monospace;
    font-size: 1rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.cyber-sim-container input[type="number"]:focus,
.cyber-sim-container select:focus {
    border-color: #ff4444;
    outline: none;
    box-shadow: 0 0 8px rgba(255,68,68,0.25);
}
.cyber-sim-hint {
    display: block;
    color: #4b5563;
    font-size: 0.72rem;
    margin-top: 6px;
    font-style: italic;
}
.cyber-sim-submit {
    width: 100%;
    background: linear-gradient(135deg, #cc2200, #ff4444);
    border: none;
    color: #ffffff;
    font-family: 'Courier New', monospace;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 14px;
    border-radius: 6px;
    cursor: pointer;
    margin-top: 8px;
    transition: background 0.2s ease, box-shadow 0.2s ease;
}
.cyber-sim-submit:hover {
    background: linear-gradient(135deg, #dd3311, #ff5555);
    box-shadow: 0 0 20px rgba(255,68,68,0.35);
}
.cyber-sim-undo {
    width: 100%;
    margin-top: 8px;
    background: transparent;
    border: 1px solid #2d3f55;
    color: #6b7280;
    font-family: 'Courier New', monospace;
    border-radius: 6px;
    padding: 10px;
    cursor: pointer;
    transition: border-color 0.2s ease, color 0.2s ease;
}
.cyber-sim-undo:hover {
    border-color: #ff4444;
    color: #ff4444;
}
.cyber-sim-event-log {
    background: #0d1117;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00ff88;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 24px;
    max-height: 220px;
    overflow-y: auto;
}
.cyber-sim-event-header {
    color: #00ff88;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 12px;
}
.cyber-sim-event-content {
    font-size: 0.82rem;
    line-height: 1.6;
    color: #8b949e;
}
.cyber-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 24px;
}
.cyber-sim-chart-wrapper {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 16px;
    height: 280px;
}
.cyber-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    overflow-x: auto;
}
.cyber-sim-container .table {
    color: #c9d1d9;
    margin-bottom: 0;
}
.cyber-sim-container .table thead th {
    border-color: #1f2d3d;
    color: #6b7280;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 10px 8px;
    background: #0a0f1e;
}
.cyber-sim-container .table td {
    border-color: #1f2d3d;
    font-size: 0.82rem;
    padding: 8px;
}
.cyber-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.02);
}
@media (max-width: 768px) {
    .cyber-sim-container {
        padding: 14px;
    }
    .cyber-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cyber-sim-kpi-value {
        font-size: 1.2rem;
    }
    .cyber-sim-control-row {
        grid-template-columns: 1fr;
        gap: 12px;
    }
    .cyber-sim-charts {
        grid-template-columns: 1fr;
    }
    .cyber-sim-chart-wrapper {
        height: 220px;
    }
}

/* EQIL 2026-11-13: accessibility, the regulatory standing card, and the debrief */
.cyber-sim-container .cyber-sim-kpi-grid { grid-template-columns: repeat(5, 1fr); }
.cyber-sim-container .cyber-sim-kpi-comp::before { background: linear-gradient(90deg, #c084fc, #d8b4fe); }
.cyber-sim-container .cyber-sim-kpi-comp .cyber-sim-kpi-value { color: #c084fc; }
.cyber-sim-container .cyber-sim-kpi-label { color: #8b93a1; }
.cyber-sim-container .cyber-sim-hint { color: #8b93a1; }
.cyber-sim-container .table thead th { color: #8b93a1; }
.cyber-sim-container button:focus-visible,
.cyber-sim-container input:focus-visible,
.cyber-sim-container select:focus-visible { outline: 3px solid #00bfff; outline-offset: 2px; }
.cyber-sim-container select option { background: #111827; color: #e5e7eb; }
.cyber-sim-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.cyber-sim-cm { text-align: left; color: #111827; }
.cyber-sim-cm-score { font-size: 2.4rem; font-weight: 800; text-align: center; }
.cyber-sim-cm-tier { font-size: 1.15rem; font-weight: 700; text-align: center; margin-bottom: 12px; }
.cyber-sim-cm-kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 8px; }
.cyber-sim-cm-kpi { border: 1px solid #d1d5db; border-radius: 6px; padding: 6px 8px; }
.cyber-sim-cm-kpi-label { font-size: 0.75rem; color: #374151; }
.cyber-sim-cm-kpi-value { font-weight: 700; }
.cyber-sim-cm-note { font-size: 0.8rem; color: #374151; }
.cyber-sim-cm h4 { font-size: 1rem; margin: 12px 0 4px; }
@media (max-width: 768px) {
    .cyber-sim-container .cyber-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .cyber-sim-cm-kpis { grid-template-columns: repeat(2, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
    .cyber-sim-container *, .cyber-sim-cm * { animation: none !important; transition: none !important; }
}
.cyber-sim-cm { background: #ffffff; padding: 12px; border-radius: 8px; }

