            if (budgetLabel) budgetLabel.textContent = t('round' + (idx + 1) + '_budget_label');
            if (budgetInput) {
                budgetInput.min = cfg.budgetMin;
                budgetInput.max = cfg.budgetMax;
                budgetInput.value = cfg.budgetDefault;
            }
            if (budgetHint) budgetHint.textContent = t('round' + (idx + 1) + '_budget_hint');
            if (strategyLabel) strategyLabel.textContent = t('round' + (idx + 1) + '_strategy_label');
            if (strategySelect) {
                var optHtml = '';
                for (var o = 1; o <= 3; o++) {
                    optHtml += '<option value="' + o + '">' + t('round' + (idx + 1) + '_opt' + o) + '</option>';
                }
                strategySelect.innerHTML = optHtml;
            }

            var eventEl = document.getElementById('eventLog');
            if (eventEl && window.mySimulation && window.mySimulation.state) {
                var evts = window.mySimulation.state.domainState.events || [];
                eventEl.innerHTML = evts.join('<br>');
            }
        }

        validateDecisions(decisions) {
            var budgetInput = document.getElementById('budgetInput');
            if (budgetInput) decisions.budget = parseFloat(budgetInput.value);

            var strategySelect = document.getElementById('strategySelect');
            if (strategySelect) decisions.strategy = parseInt(strategySelect.value);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, 3);
            var cfg = this.ROUND_CONFIGS[idx];

            if (isNaN(decisions.budget) || decisions.budget < cfg.budgetMin || decisions.budget > cfg.budgetMax) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.strategy || decisions.strategy < 1 || decisions.strategy > 3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('strategy_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        _secGain(b) {
            var k = this.SEC_K;
            return Math.round(70 * (1 - Math.exp(-b / k)) / (1 - Math.exp(-2000 / k)));
        }

        _rebuildData(b) {
            return Math.min(78, (Math.max(b, 500) / 3200) * 78);
        }

        _shortfall(ds) {
            return Math.max(0, this.CASH_FLOOR - (ds.cash || 0));
        }

        _baseScore(ds) {
            return (ds.reputation || 0) * 0.25 + (ds.dataIntegrity || 0) * 0.25 + (ds.securityLevel || 0) * 0.25 + (ds.compliance || 0) * 0.25;
        }

        _composite(ds) {
            var s = Math.round(this._baseScore(ds) - this._shortfall(ds) / this.SHORTFALL_PER_POINT);
            return Math.max(0, Math.min(100, s));
        }

        _tierId(score) {
            if (score >= 75) return 'excellent';
            if (score >= 60) return 'strong';
            if (score >= 45) return 'adequate';
            return 'needs_improvement';
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            if (typeof ds.keyRoll !== 'number') ds.keyRoll = Math.random();
            if (typeof ds.malwareRoll !== 'number') ds.malwareRoll = Math.random();
            var period = state.currentPeriod;
            var cost = 0;
            var repDelta = 0;
            var dataDelta = 0;
            var secDelta = 0;
            var compDelta = 0;
            var eventText = '';
            var t = window.mySimulation.t.bind(window.mySimulation);

            if (period === 1) {
                cost = d.budget * 1000;
                if (d.strategy === 2) cost += 50000;
                if (d.strategy === 3) cost += 100000;
                ds.forensicQuality = Math.min(1, d.budget / 300);
                repDelta = d.strategy === 3 ? 0 : d.strategy === 2 ? -5 : -15;
                secDelta = 0;
                dataDelta = 0;
                eventText = t('event_r1_forensic') + ' (' + Math.round(ds.forensicQuality * 100) + '%)';
                if (d.strategy === 3) {
                    eventText += '<br>' + t('event_r1_full_activation');
                } else if (d.strategy === 2) {
                    eventText += '<br>' + t('event_r1_board_alert');
                } else {
                    eventText += '<br>' + t('event_r1_containment');
                }
            }

            if (period === 2) {
                if (d.strategy === 1) {
                    cost = 475000;
                    var successRate = ds.forensicQuality > 0.7 ? 0.9 : 0.8;
                    var roll = ds.keyRoll;
                    if (roll < successRate) {
                        dataDelta = 89 - ds.dataIntegrity;
                        eventText = t('event_r2_pay_success');
                    } else {
                        dataDelta = 45 - ds.dataIntegrity;
                        eventText = t('event_r2_pay_partial');
                    }
                    repDelta = -15;
                    secDelta = 0;
                    ds.ransomPaid = true;
                    var residualRoll = ds.malwareRoll;
                    if (ds.forensicQuality < 0.5 && residualRoll < 0.3) {
                        secDelta = -10;
                        eventText += '<br>' + t('event_r2_malware_detected');
                    }
                } else if (d.strategy === 2) {
                    cost = Math.max(d.budget, 500) * 1000;
                    dataDelta = this._rebuildData(d.budget) - ds.dataIntegrity;
                    repDelta = 5;
                    secDelta = 15;
                    ds.ransomPaid = false;
                    eventText = t('event_r2_rebuild');
                } else {
                    // Hybrid: the same key draw as paying (case exhibit 2: it carries the risks of both
                    // paths); if the key fails, the parallel rebuild recovers what a rebuild of that budget would
                    cost = 475000 + Math.max(d.budget, 200) * 1000;
                    var hybridRate = ds.forensicQuality > 0.7 ? 0.9 : 0.8;
                    if (ds.keyRoll < hybridRate) {
                        dataDelta = Math.min(92, 89 + (Math.max(d.budget, 200) / 2000) * 3) - ds.dataIntegrity;
                        eventText = t('event_r2_hybrid');
                    } else {
                        dataDelta = Math.max(45, this._rebuildData(d.budget)) - ds.dataIntegrity;
                        eventText = t('event_r2_hybrid_keyfail');
                    }
                    repDelta = -5;
                    secDelta = 10;
                    ds.ransomPaid = true;
                }
            }

            if (period === 3) {
                var baseLegal = d.strategy === 1 ? 100000 : d.strategy === 2 ? 150000 : 300000;
                cost = d.budget * 1000 + baseLegal;
                compDelta = d.strategy === 1 ? 30 : d.strategy === 2 ? 15 : -20;
                if (ds.ransomPaid) compDelta -= 10;
                var commEffect = Math.min(1, d.budget / 500);
                var timingRep = d.strategy === 1 ? 10 : d.strategy === 2 ? 5 : -10;
                repDelta = Math.round(commEffect * 15 + timingRep);
                secDelta = 0;
                dataDelta = 2;
                if (d.strategy === 1) {
                    eventText = t('event_r3_immediate');
                } else if (d.strategy === 2) {
                    eventText = t('event_r3_within48');
                } else {
                    eventText = t('event_r3_delayed');
                }
                if (ds.ransomPaid) {
                    eventText += '<br>' + t('event_r3_aml_risk');
                }
            }

            if (period === 4) {
                var insuranceCost = d.strategy === 3 ? 180000 : d.strategy === 2 ? 90000 : 0;
                cost = d.budget * 1000 + insuranceCost;
                secDelta = this._secGain(d.budget);
                repDelta = 10;
                dataDelta = 5;
                compDelta = d.strategy >= 2 ? 10 : 0;
                eventText = t('event_r4_security');
                if (d.strategy === 3) {
                    eventText += '<br>' + t('event_r4_insurance_full');
                } else if (d.strategy === 2) {
                    eventText += '<br>' + t('event_r4_insurance_basic');
                } else {
                    eventText += '<br>' + t('event_r4_no_insurance');
                }
            }

            ds.cash -= cost;
            ds.totalSpent += cost;
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + repDelta));
            ds.dataIntegrity = Math.max(0, Math.min(100, Math.round(ds.dataIntegrity + dataDelta)));
            ds.securityLevel = Math.max(0, Math.min(100, ds.securityLevel + secDelta));
            ds.compliance = Math.max(0, Math.min(100, ds.compliance + compDelta));

            ds.costHistory.push(cost);
            ds.reputationHistory.push(ds.reputation);
            ds.securityHistory.push(ds.securityLevel);
            ds.dataHistory.push(ds.dataIntegrity);
            ds.events.push('<b>R' + period + ':</b> ' + eventText);

            // Platform score: one composite for every round and the debrief (equal weights on
            // reputation, data integrity, security and regulatory standing, less the liquidity shortfall)
            var overallScore = this._composite(ds);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var results = {
                period: period,
                budget: d.budget,
                strategy: d.strategy,
                cost: cost,
                reputationDelta: repDelta,
                dataDelta: Math.round(dataDelta),
                secDelta: secDelta,
                cash: ds.cash,
                reputation: ds.reputation,
                dataIntegrity: ds.dataIntegrity,
                securityLevel: ds.securityLevel,
                compliance: ds.compliance,
                choice: 'round' + period + '_opt' + d.strategy,
                overallScore: overallScore,
                score: overallScore
            };

            // Advance the briefing and controls to the next round synchronously: the framework
            // increments currentPeriod right after this returns, so N plus 1 is the next round.
            // Nothing to advance after the last round.
            if (state.currentPeriod < this.ROUND_CONFIGS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            return results;
        }

        setupUI(uiManager) {
            // After an undo the framework rewinds the round but leaves the next round on screen:
            // show the briefing, range and options of the round being replayed
            var self = this;
            var sim = window.mySimulation;
            if (!this._undoBound && sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                this._undoBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
            }
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
