            uiManager.bind('reputationDisplay', 'domainState.reputation',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('dataDisplay', 'domainState.dataIntegrity',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('securityDisplay', 'domainState.securityLevel',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('complianceDisplay', 'domainState.compliance',
                function(v) { return Math.round(v) + '/100'; });
        }

