        getChartData(state) {
            var labels = state.domainState.costHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                costChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.costHistory }]
                },
                scoreChart: {
