                        { data: state.domainState.reputationHistory },
                        { data: state.domainState.dataHistory },
                        { data: state.domainState.securityHistory }
                    ]
                }
            };
        }

        _t() {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
        }

        _money(v) {
            var n = Math.round(v || 0);
            return (n < 0 ? '-$' : '$') + Math.abs(n).toLocaleString('en-US');
        }

        _fill(text, vals) {
            var out = String(text);
            Object.keys(vals).forEach(function(k) { out = out.split('{' + k + '}').join(String(vals[k])); });
            return out;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var t = this._t();
            var self = this;
            var last = history[history.length - 1];
            var ds = last.domainState || {};
            var byRound = {};
            history.forEach(function(h) { if (h && h.period) byRound[h.period] = h; });
            var dec = function(p) { var h = byRound[p]; return (h && h.decisions) ? h.decisions : {}; };
            var res = function(p) { var h = byRound[p]; return (h && h.results) ? h.results : {}; };

            var score = this._composite(ds);
            var tier = this._tierId(score);
            var shortfall = this._shortfall(ds);
            var liqPoints = Math.round(shortfall / this.SHORTFALL_PER_POINT);
            var r1 = dec(1), r2 = dec(2), r3 = dec(3), r4 = dec(4);
            var keyFailed = !!(r2.strategy !== 2 && byRound[2] && typeof ds.keyRoll === 'number' &&
                ds.keyRoll >= (ds.forensicQuality > 0.7 ? 0.9 : 0.8));
            var vals = {
                cash: this._money(ds.cash), floor: this._money(this.CASH_FLOOR), pts: liqPoints,
                data: Math.round(res(2).dataIntegrity || 0), sec: '$' + Math.round(r4.budget || 0) + 'K',
                comm: '$' + Math.round(r3.budget || 0) + 'K', forensic: '$' + Math.round(r1.budget || 0) + 'K'
            };

            var turning;
            if (shortfall > 0) turning = t('tp_liquidity');
            else if (r3.strategy === 3) turning = t('tp_late_notice');
            else if (keyFailed) turning = t('tp_key_failed');
            else turning = t('tp_none');
            turning = this._fill(turning, vals);

            var insights = [];
            var i1 = this._fill(t(r1.strategy === 1 ? 'ins_r1_contain' : r1.strategy === 2 ? 'ins_r1_board' : 'ins_r1_full'), vals);
            if ((r1.budget || 0) > 210 && r2.strategy === 2) i1 += ' ' + this._fill(t('ins_r1_forensic_unused'), vals);
            insights.push(i1);
            var k2 = 'ins_r2_rebuild';
            if (r2.strategy === 1) k2 = keyFailed ? 'ins_r2_pay_fail' : 'ins_r2_pay_ok';
            else if (r2.strategy === 3) k2 = keyFailed ? 'ins_r2_hybrid_fail' : 'ins_r2_hybrid_ok';
            insights.push(this._fill(t(k2), vals));
            insights.push(this._fill(t(r3.strategy === 1 ? 'ins_r3_immediate' : r3.strategy === 2 ? 'ins_r3_48h' : 'ins_r3_late'), vals));
            var b4 = r4.budget || 0;
            insights.push(this._fill(t(b4 >= 1000 ? 'ins_r4_over' : b4 < 400 ? 'ins_r4_low' : 'ins_r4_menu'), vals));
            insights.push(this._fill(t(shortfall > 0 ? 'ins_cash_below' : 'ins_cash_ok'), vals));

            return {
                compositeScore: score,
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                totalSpent: ds.totalSpent || 0,
                cash: ds.cash || 0,
                liquidityPoints: liqPoints,
                reputation: ds.reputation || 0,
                dataIntegrity: ds.dataIntegrity || 0,
                securityLevel: ds.securityLevel || 0,
                compliance: ds.compliance || 0,
                ransomPaid: !!ds.ransomPaid,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: t('tier_' + tier),
                turningPoint: turning,
                insights: insights,
                questions: [t('dq_1'), t('dq_2')],
                totalPeriods: history.length
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = this._t();
            var self = this;
            if (summary.score === undefined) {
                return '<div class="cyber-sim-cm"><p>' + t('cm_none') + '</p></div>';
            }
            var kpi = function(label, value) {
                return '<div class="cyber-sim-cm-kpi"><div class="cyber-sim-cm-kpi-label">' + label + '</div><div class="cyber-sim-cm-kpi-value">' + value + '</div></div>';
            };
            var h = '<div class="cyber-sim-cm" role="status">';
            h += '<div class="cyber-sim-cm-score">' + summary.score + '/100</div>';
            h += '<div class="cyber-sim-cm-tier">' + summary.performanceLabel + '</div>';
            h += '<div class="cyber-sim-cm-kpis">';
            h += kpi(t('reputation_label'), Math.round(summary.reputation) + '/100');
            h += kpi(t('data_label'), Math.round(summary.dataIntegrity) + '%');
            h += kpi(t('security_label'), Math.round(summary.securityLevel) + '%');
            h += kpi(t('compliance_label'), Math.round(summary.compliance) + '/100');
            h += kpi(t('cash_label'), self._money(summary.cash));
            h += kpi(t('cm_liquidity'), summary.liquidityPoints > 0 ? '-' + summary.liquidityPoints : '0');
            h += '</div>';
            h += '<p class="cyber-sim-cm-note">' + t('cm_formula') + '</p>';
            h += '<h4>' + t('cm_turning') + '</h4><p>' + summary.turningPoint + '</p>';
            h += '<h4>' + t('cm_insights') + '</h4><ul>';
            (summary.insights || []).forEach(function(i) { h += '<li>' + i + '</li>'; });
            h += '</ul><h4>' + t('cm_questions') + '</h4><ol>';
            (summary.questions || []).forEach(function(q) { h += '<li>' + q + '</li>'; });
            h += '</ol></div>';
            return h;
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod;
            if (period === 1 && results.cost > 350000) return window.mySimulation.t('hint_r1_high_spend');
            if (period === 2 && state.domainState.ransomPaid) return window.mySimulation.t('hint_r2_paid');
            if (period === 2 && !state.domainState.ransomPaid) return window.mySimulation.t('hint_r2_rebuild');
            if (period === 3 && results.strategy === 3) return window.mySimulation.t('hint_r3_delayed');
            if (period === 3 && state.domainState.ransomPaid) return window.mySimulation.t('hint_r3_aml');
            if (period === 4 && results.secDelta < 30) return window.mySimulation.t('hint_r4_low_security');
            return null;
        }

